#include <stdio.h>
#include <string.h>

#define MAXN 20005
#define ALPHA 36
#define MAXNODES 200052

static int child_[MAXNODES][ALPHA];
static int cnt_[MAXNODES];
static int vis_[MAXNODES];

static char pw[MAXN][12];
static int plen[MAXN];
static int nodeCount = 1;

static inline int idx(char c) {
    return (c >= '0' && c <= '9') ? (26 + (c - '0')) : (c - 'a');
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        if (scanf("%11s", pw[i]) != 1) return 0;
        int len = (int)strlen(pw[i]);
        plen[i] = len;
        int cur = 0;
        for (int k = 0; k < len; k++) {
            int c = idx(pw[i][k]);
            int nx = child_[cur][c];
            if (!nx) {
                nx = ++nodeCount;
                child_[cur][c] = nx;
            }
            cur = nx;
        }
        cnt_[cur]++;
    }

    long long total = 0;
    for (int j = 0; j < n; j++) {
        const char *s = pw[j];
        int L = plen[j];
        int stamp = j + 1;
        for (int i = 0; i < L; i++) {
            int cur = 0;
            for (int k = i; k < L; k++) {
                cur = child_[cur][idx(s[k])];
                if (!cur) break;
                if (cnt_[cur] && vis_[cur] != stamp) {
                    vis_[cur] = stamp;
                    total += cnt_[cur];
                }
            }
        }
    }

    printf("%lld\n", total - (long long)n);
    return 0;
}
